package mocks

import (
	"context"

	"github.com/get-phanuwat-api1/product-service/internal/repository"
)

// FakeTransactor is a hand-written fake of repository.Transactor (not generated by mockery):
// it simply runs fn and counts calls, which is all service tests need.
type FakeTransactor struct{ Calls int }

var _ repository.Transactor = (*FakeTransactor)(nil)

func (t *FakeTransactor) WithinTransaction(ctx context.Context, fn func(ctx context.Context) error) error {
	t.Calls++
	return fn(ctx)
}
